cat > /tmp/sdk-test.js << 'EOF'
// SDK usage example - demonstrating threshold support
import { Eval } from 'frai-core';

const dataset = {
  outputs: ['hello', 'world'],
  references: ['hello', 'world'],
  outputsPath: '/tmp/out.json',
  referencesPath: '/tmp/ref.json'
};

const evaluations = Eval.runEvaluations({
  outputs: dataset.outputs,
  references: dataset.references
});

console.log('Evaluations:', evaluations.map(e => ({ id: e.id, score: e.score })));

// SDK users can now pass thresholds to generateReport
const report = Eval.generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds: {
    exact_match: 0.9,
    toxicity: 0.8
  }
});

console.log('Report passed:', report.passed);
console.log('Thresholds:', report.thresholds);
EOF
node /tmp/sdk-test.js 2>&1

cat > sdk-demo.mjs << 'EOF'
import { Eval } from './packages/frai-core/src/index.js';

console.log('SDK Users - Threshold Support Demo');
console.log('====================================');

const evaluations = Eval.runEvaluations({
  outputs: ['hello', 'world'],
  references: ['hello', 'world']
});

console.log('\nEvaluations metrics:');
evaluations.forEach(e => console.log(`  ${e.id}: ${e.score}`));

const report = Eval.generateReport({
  evaluations,
  outputsPath: '/tmp/out.json',
  referencesPath: '/tmp/ref.json',
  thresholds: {
    exact_match: 0.9,
    toxicity: 0.8
  }
});

console.log('\nReport with thresholds:');
console.log(`  passed: ${report.passed}`);
console.log(`  thresholds (${report.thresholds.length} items):`);
report.thresholds.forEach(t => {
  console.log(`    - ${t.metric}: ${t.passed ? 'PASS' : 'FAIL'} (min: ${t.min}, score: ${t.score})`);
});
EOF
node sdk-demo.mjs
